('5a4e0011-0000-4000-8000-000000002580', '5a4e0010-0000-4000-8000-000000000462', '5a4e0000-0000-4000-8000-000000040009', 'Açık hava, Çankaya. Yağmur planı için alternatif de var. Ekibiniz kaç kişi geliyor?', 'text', NULL, pg_temp.t(3867.45), pg_temp.t(3841.33)),
('5a4e0011-0000-4000-8000-000000002581', '5a4e0010-0000-4000-8000-000000000462', '5a4e0000-0000-4000-8000-000000010009', 'Anladım, teşekkürler. Teklifi hazırladım; %30 kapora ile tarih kesinleşir, kalanı etkinlik günü. İptal koşulları teklifte yazıyor.', 'text', NULL, pg_temp.t(3857.47), NULL),
('5a4e0011-0000-4000-8000-000000002582', '5a4e0010-0000-4000-8000-000000000462', '5a4e0000-0000-4000-8000-000000010009', 'Teklif gönderildi', 'quote', '5a4e0012-0000-4000-8000-000000000347', pg_temp.t(3854.14), pg_temp.t(3849.03)),
('5a4e0011-0000-4000-8000-000000002583', '5a4e0010-0000-4000-8000-000000000463', '5a4e0000-0000-4000-8000-000000040009', 'Merhaba, 02.07 tarihinde Bursa''da düğün organizasyonumuz var. Yaklaşık 100 kişi bekliyoruz. Müsait misiniz, fiyat bilgisi alabilir miyim?', 'text', NULL, pg_temp.t(3133.54), pg_temp.t(3132.59)),
('5a4e0011-0000-4000-8000-000000002584', '5a4e0010-0000-4000-8000-000000000463', '5a4e0000-0000-4000-8000-000000010022', 'Merhaba, teşekkürler. 02.07 tarihi şu an için müsait. Detayları konuşup size özel bir teklif hazırlayayım; mekan ve saat bilgisini de alabilir miyim?', 'text', NULL, pg_temp.t(3133.21), pg_temp.t(3112.08)),
('5a4e0011-0000-4000-8000-000000002585', '5a4e0010-0000-4000-8000-000000000463', '5a4e0000-0000-4000-8000-000000040009', 'Teşekkürler. Toplam süre 5-6 saat olur. Bütçe konusunda biraz esneğiz, önemli olan deneyim.', 'text', NULL, pg_temp.t(3117.19), pg_temp.t(3113.63)),
('5a4e0011-0000-4000-8000-000000002586', '5a4e0010-0000-4000-8000-000000000463', '5a4e0000-0000-4000-8000-000000010022', 'Süper. Açık hava için ek ekipman gerekebilir, onu teklife ayrı kalem olarak ekledim. İsterseniz çıkarabiliriz.', 'text', NULL, pg_temp.t(3116.25), pg_temp.t(3098.34)),
('5a4e0011-0000-4000-8000-000000002587', '5a4e0010-0000-4000-8000-000000000464', '5a4e0000-0000-4000-8000-000000040018', 'Merhaba, 13.11 tarihinde İstanbul''da konferans organizasyonumuz var. Yaklaşık 150 kişi bekliyoruz. Müsait misiniz, fiyat bilgisi alabilir miyim?', 'text', NULL, pg_temp.t(3601.56), pg_temp.t(3581.75)),
('5a4e0011-0000-4000-8000-000000002588', '5a4e0010-0000-4000-8000-000000000465', '5a4e0000-0000-4000-8000-000000030001', 'Merhaba, 04.08 tarihinde Antalya''da kurumsal organizasyonumuz var. Yaklaşık 100 kişi bekliyoruz. Müsait misiniz, fiyat bilgisi alabilir miyim?', 'text', NULL, pg_temp.t(2534.75), pg_temp.t(2516.52)),
('5a4e0011-0000-4000-8000-000000002589', '5a4e0010-0000-4000-8000-000000000465', '5a4e0000-0000-4000-8000-000000010108', 'Selam, yazdığınız için teşekkürler. Antalya için ulaşım dahil fiyat verebilirim. Program akışını paylaşırsanız teklifi ona göre netleştiririm.', 'text', NULL, pg_temp.t(2533.11), NULL),
('5a4e0011-0000-4000-8000-000000002590', '5a4e0010-0000-4000-8000-000000000465', '5a4e0000-0000-4000-8000-000000030001', 'Mekan Belek tarafında, kapalı salon. Saat 19.00''da başlayıp gece yarısına kadar sürecek.', 'text', NULL, pg_temp.t(2522.02), pg_temp.t(2492.57)),
('5a4e0011-0000-4000-8000-000000002591', '5a4e0010-0000-4000-8000-000000000465', '5a4e0000-0000-4000-8000-000000010108', 'Anladım, teşekkürler. Teklifi hazırladım; %30 kapora ile tarih kesinleşir, kalanı etkinlik günü. İptal koşulları teklifte yazıyor.', 'text', NULL, pg_temp.t(2518.48), NULL),
('5a4e0011-0000-4000-8000-000000002592', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000040008', 'Merhaba, 24.12 tarihinde Ankara''da kına gecesi organizasyonumuz var. Yaklaşık 80 kişi bekliyoruz. Müsait misiniz, fiyat bilgisi alabilir miyim?', 'text', NULL, pg_temp.t(846.66), pg_temp.t(816.93)),
('5a4e0011-0000-4000-8000-000000002593', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000010074', 'Merhaba, teşekkürler. 24.12 tarihi şu an için müsait. Detayları konuşup size özel bir teklif hazırlayayım; mekan ve saat bilgisini de alabilir miyim?', 'text', NULL, pg_temp.t(808.45), pg_temp.t(802.44)),
('5a4e0011-0000-4000-8000-000000002594', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000040008', 'Açık hava, Keçiören. Yağmur planı için alternatif de var. Ekibiniz kaç kişi geliyor?', 'text', NULL, pg_temp.t(788.43), pg_temp.t(777.50)),
('5a4e0011-0000-4000-8000-000000002595', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000010074', 'Tamamdır. Ekip 2 kişi geliyor, ulaşım bizden. Teklif ekte, geçerlilik 14 gün.', 'text', NULL, pg_temp.t(779.56), pg_temp.t(763.99)),
('5a4e0011-0000-4000-8000-000000002596', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000010074', 'Teklif gönderildi', 'quote', '5a4e0012-0000-4000-8000-000000000348', pg_temp.t(773.10), pg_temp.t(763.87)),
('5a4e0011-0000-4000-8000-000000002597', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000040008', 'Teklif uygun, onaylıyorum. Görüşmek üzere!', 'text', NULL, pg_temp.t(720.27), pg_temp.t(694.57)),
('5a4e0011-0000-4000-8000-000000002598', '5a4e0010-0000-4000-8000-000000000466', '5a4e0000-0000-4000-8000-000000010074', '✓ Teklif onaylandı', 'system', '5a4e0012-0000-4000-8000-000000000348', pg_temp.t(720.22), pg_temp.t(712.63))
